class DataInformationBlock(TelegramField):
    EXTENSION_BIT_MASK = 0x80  # 1000 0000
    FUNCTION_MASK = 0x30   # 0011 0000
    DATA_FIELD_MASK = 0x0F  # 0000 1111
    MORE_RECORDS_FOLLOW = 0x1F  # 0001 1111

    def __init__(self, parts=None):
        super(DataInformationBlock, self).__init__(parts)

    @property
    def has_extension_bit(self):
        """Check for extension bit on last byte"""
        try:
            return (self.parts[-1] & self.EXTENSION_BIT_MASK) > 0
        except IndexError:
            return False

    @property
    def has_lvar_bit(self):
        """returns true if this record carries an LVAR byte (variable length)"""
        # Data field 1101b selects variable length. The old check looked at
        # the extension bit of the first DIFE, so plain LVAR records (no DIFE)
        # were not detected and multi-DIFE records were treated as LVAR.
        try:
            return (self.parts[0] & self.DATA_FIELD_MASK) == 0x0D
        except IndexError:
            return False

    @property
    def is_eoud(self):
        """Check for end of user data (manufacturer specific / more records)"""
        try:
            dif = self.parts[0]
            # Ignore a stray extension bit so 0x8F/0x9F still end the
            # standard records and the remaining unknown payload is kept.
            if (dif & 0x7F) in (0x0F, 0x1F):
                return True
        except IndexError:
            pass

        return False

    @property
    def is_manufacturer_specific(self):
        """Check for manufacturer specific / unknown payload record"""
        try:
            dif = self.parts[0] & 0x7F
            # 0x0F: manufacturer specific through end of user data.
            # 0x1F: same meaning, and more records follow in the next telegram.
            if dif in (0x0F, 0x1F):
                return True
        except IndexError:
            pass

        return False

    @property
    def more_records_follow(self):
        try:
            dif = self.parts[0]
            return (dif & 0x7F) == self.MORE_RECORDS_FOLLOW
        except IndexError:
            pass

        return False

    @property
    def function_type(self):
        try:
            dif = self.parts[0]
        except IndexError:
            return FunctionType.INSTANTANEOUS_VALUE

        if self.is_eoud and self.more_records_follow:
            return FunctionType.MORE_RECORDS_FOLLOW

        # Any special-function DIF (data field 1111b). Comparing only the
        # exact bytes 0x0F/0x2F left 0x4F/0x7F/0x8F decoded as a normal
        # instantaneous/min/max/error value (wrong type) and the following
        # unknown payload was parsed as further records.
        if (dif & self.DATA_FIELD_MASK) == 0x0F:
            stripped = dif & 0x7F
            if stripped == self.MORE_RECORDS_FOLLOW:
                return FunctionType.MORE_RECORDS_FOLLOW
            if stripped == 0x2F:
                return FunctionType.SPECIAL_FUNCTION_FILL_BYTE
            return FunctionType.SPECIAL_FUNCTION

        return FunctionType((dif & self.FUNCTION_MASK) >> 4)

    @property
    def is_variable_length(self):
        try:
            dif = self.parts[0]
            return (dif & self.DATA_FIELD_MASK) == 0x0D
        except IndexError:
            pass

        return False

    @property
    def length_encoding(self):
        len_enc = self.parts[0] & self.DATA_FIELD_MASK

        # EN 13757-3 data field lengths, in bytes:
        #   0 none, 1-4 int, 5 real(4), 6 int(6), 7 int(8), 8 selection,
        #   9-12 BCD of 1/2/3/4 bytes, 13 variable (size is the LVAR byte),
        #   14 BCD of 6 bytes (12 digits), 15 special function.
        # 8-digit BCD was 5 bytes (len_enc-7), so the next DIF was swallowed
        # and every later record was shifted (wrong count, values, units, types).
        # Variable length was a fixed 6 bytes, so LVAR payloads (and a trailing
        # unknown/manufacturer block) were split or truncated.
        return {
            0: (0, DataEncoding.ENCODING_NULL),
            1: (len_enc, DataEncoding.ENCODING_INTEGER),  # 1 byte int [8 bit]
            2: (len_enc, DataEncoding.ENCODING_INTEGER),  # 2 byte int [16 bit] or date...
            3: (len_enc, DataEncoding.ENCODING_INTEGER),  # 3 byte int [24 bit]
            4: (len_enc, DataEncoding.ENCODING_INTEGER),  # 4 byte int [32 bit] or date...
            5: (4, DataEncoding.ENCODING_REAL),  # 4 byte float [32 bit]
            6: (6, DataEncoding.ENCODING_INTEGER),  # 6 byte int [48 bit]
            7: (8, DataEncoding.ENCODING_INTEGER),  # 8 byte int [64 bit]
            8: (0, DataEncoding.ENCODING_NULL),  # Nothing...
            9: (len_enc - 8, DataEncoding.ENCODING_BCD),  # 2 digit BCD [8 bit]
            10: (len_enc - 8, DataEncoding.ENCODING_BCD),  # 4 digit BCD [16 bit]
            11: (len_enc - 8, DataEncoding.ENCODING_BCD),  # 6 digit BCD [24 bit]
            12: (len_enc - 8, DataEncoding.ENCODING_BCD),  # 8 digit BCD [32 bit]
            13: (0, DataEncoding.ENCODING_VARIABLE_LENGTH),  # variable length (LVAR)
            14: (6, DataEncoding.ENCODING_BCD),  # 12 digit BCD [48 bit]
            15: (0, DataEncoding.ENCODING_NULL)  # Special Function
        }[len_enc]

