class DataInformationBlock(TelegramField):
    EXTENSION_BIT_MASK = 0x80  # 1000 0000
    FUNCTION_MASK = 0x30   # 0011 0000
    DATA_FIELD_MASK = 0x0F  # 0000 1111
    MORE_RECORDS_FOLLOW = 0x1F  # 0001 1111

    def __init__(self, parts=None):
        super(DataInformationBlock, self).__init__(parts)

    @property
    def has_extension_bit(self):
        """Check for extension bit on last byte"""
        try:
            return (self.parts[-1] & self.EXTENSION_BIT_MASK) > 0
        except IndexError:
            return False

    @property
    def has_lvar_bit(self):
        """True when the DIF selects variable-length (LVAR) data.

        LVAR is data-field 0xD on the DIF. It is not the extension bit of a
        following DIFE; that old check missed plain variable records (wrong
        value type) and fired for multi-DIFE records that are not LVAR.
        """
        try:
            return (self.parts[0] & self.DATA_FIELD_MASK) == 0x0D
        except IndexError:
            return False

    @property
    def is_eoud(self):
        """Check for end of user data bit VIF byte"""
        try:
            dif = self.parts[0]
            if dif in [0x0F, 0x1F]:
                return True
        except IndexError:
            pass

        return False

    @property
    def is_manufacturer_specific(self):
        """Check for manufacturer specific record"""
        try:
            dif = self.parts[0]
            # 0x0F: manufacturer specific through end of user data.
            # 0x1F: same payload meaning, plus more records follow later.
            # Unknown trailing payloads were dropped when only 0x0F matched,
            # so the record list was short (index errors) and the payload
            # was parsed as further records with garbage values/units/types.
            if dif in (0x0F, 0x1F):
                return True
        except IndexError:
            pass

        return False

    @property
    def more_records_follow(self):
        try:
            dif = self.parts[0]
            return dif == self.MORE_RECORDS_FOLLOW
        except IndexError:
            pass

        return False

    @property
    def function_type(self):
        if self.is_eoud and self.more_records_follow:
            return FunctionType.MORE_RECORDS_FOLLOW

        elif self.parts[0] == 0x0F or self.parts[0] == 0x1F:
            # Manufacturer specific / unknown payload.
            return FunctionType.SPECIAL_FUNCTION

        elif self.parts[0] == 0x2F:
            return FunctionType.SPECIAL_FUNCTION_FILL_BYTE

        return FunctionType(
            (self.parts[0] & self.FUNCTION_MASK) >> 4)

    @property
    def is_variable_length(self):
        try:
            dif = self.parts[0]
            return (dif & self.DATA_FIELD_MASK) == 0x0D
        except IndexError:
            pass

        return False

    @property
    def length_encoding(self):
        len_enc = self.parts[0] & self.DATA_FIELD_MASK

        # Byte length and coding of the DIF data field (EN 13757-3).
        # 8-digit BCD is 4 bytes; len_enc-7 was 5 and ate the next DIF, so
        # later records (WEPTECH frames, frames with a trailing unknown
        # payload) had the wrong count, values, units and types.
        # Variable-length data has no fixed size; the LVAR byte that follows
        # the VIB defines it. A fixed 6 shifted every record after an LVAR.
        return {
            0: (0, DataEncoding.ENCODING_NULL),
            1: (len_enc, DataEncoding.ENCODING_INTEGER),  # 1 byte int [8 bit]
            2: (len_enc, DataEncoding.ENCODING_INTEGER),  # 2 byte int [16 bit] or date...
            3: (len_enc, DataEncoding.ENCODING_INTEGER),  # 3 byte int [24 bit]
