    MORE_RECORDS_FOLLOW = 0x1F  # 0001 1111

    def __init__(self, parts=None):
        super(DataInformationBlock, self).__init__(parts)

    @property
    def has_extension_bit(self):
        """Check for extension bit on last byte"""
        try:
            # Special functions (data field 1111b) are a single DIF. Bit 7 must
            # not pull the following unknown payload in as a DIFE.
            if (self.parts[0] & self.DATA_FIELD_MASK) == 0x0F:
                return False
            return (self.parts[-1] & self.EXTENSION_BIT_MASK) > 0
        except IndexError:
            return False

    @property
    def has_lvar_bit(self):
        """returns true if first VIFE has LVAR active"""
        try:
            # LVAR is DIF data-field 0xD, not the extension bit of a DIFE.
            return (self.parts[0] & self.DATA_FIELD_MASK) == 0x0D
        except IndexError:
            return False

    @property
    def is_eoud(self):
        """Check for end of user data bit VIF byte"""
        try:
            dif = self.parts[0] & 0x7F
            if dif in (0x0F, 0x1F):
                return True
        except IndexError:
            pass

        return False

    @property
    def is_manufacturer_specific(self):
        """Check for manufacturer specific record"""
        try:
            # 0x0F only. 0x1F is "more records follow" and must not be treated
            # as the manufacturer payload or the previous record is flagged.
            dif = self.parts[0] & 0x7F
            if dif == 0x0F:
                return True
        except IndexError:
            pass

        return False

    @property
    def more_records_follow(self):
        try:
            dif = self.parts[0] & 0x7F
            return dif == self.MORE_RECORDS_FOLLOW
        except IndexError:
            pass

        return False

