    def function_type(self):
        dif = self.parts[0]

        # Any data-field of 0xF is a special function. Leaving 0x4F/0x7F/0x8F
        # as instantaneous/min/max/error made the following bytes (unknown
        # payload, or the next real DIF) decode as further records.
        if (dif & self.DATA_FIELD_MASK) == 0x0F:
            stripped = dif & 0x7F
            if stripped == self.MORE_RECORDS_FOLLOW:
